(4520613, 651382, 80058, '<td valign="top">Nice and simple just how I like it! Neat subject, nice and sharp, great composition and beautiful lighting ;]</td>', 'Nice and simple just how I like it! Neat subject, nice and sharp, great composition and beautiful lighting ;]', '2008-02-27 08:08:42.000000', NULL, 1),
