(4523603, 651962, 32872, '<td valign="top">Love your abstract!  Reminds me of tinsil.</td>', 'Love your abstract!  Reminds me of tinsil.', '2008-02-27 21:10:23.000000', NULL, 1),
(4523605, 650210, 32872, '<td valign="top">Wow very trippy image!</td>', 'Wow very trippy image!', '2008-02-27 21:11:19.000000', NULL, 1),
(4523631, 650610, 80807, '<td valign="top">An Excellent choice of subject!  Original and well done!</td>', 'An Excellent choice of subject!  Original and well done!', '2008-02-27 21:38:04.000000', NULL, 1),
