(4527698, 649288, 27556, '<td valign="top">very simple but effective. Im seeing a bit of grain in the stones shadowe though</td>', 'very simple but effective. Im seeing a bit of grain in the stones shadowe though', '2008-02-29 10:27:13.000000', NULL, 1),
