(4529984, 651963, 46177, '<td valign="top">Very well done, love the angle and the lighting. 10</td>', 'Very well done, love the angle and the lighting. 10', '2008-03-01 10:23:33.000000', NULL, 1),
(4529986, 651812, 46177, '<td valign="top">Simply beautiful, one  of my top picks for the challenge. I gave you a 10.</td>', 'Simply beautiful, one  of my top picks for the challenge. I gave you a 10.', '2008-03-01 10:24:04.000000', NULL, 1),
