(4530187, 651840, 27556, '<td valign="top">This is a fantastic macro. I love all of the detail that I am seeing on the body, but im not a fan of the pink forground and green background since Im looking for a b&amp;w recreation. But this shot outside of this challenge is truly amazing.</td>', 'This is a fantastic macro. I love all of the detail that I am seeing on the body, but im not a fan of the pink forground and green background since Im looking for a b&w recreation. But this shot outside of this challenge is truly amazing.', '2008-03-01 11:24:07.000000', NULL, 1),
(4530449, 650596, 7743, '<td valign="top">You probably meant the cows to be your subject but they are too small to be of any significance in the image.  In that regard this image would be a big stretch to meet the challenge.</td>', 'You probably meant the cows to be your subject but they are too small to be of any significance in the image.  In that regard this image would be a big stretch to meet the challenge.', '2008-03-01 12:45:08.000000', NULL, 1),
