(4535280, 651667, 27556, '<td valign="top">How ominous. I think this might have benifited from a slightly different crop if the tree was more to the right and there was some more negative space I think it could have been more striking.</td>', 'How ominous. I think this might have benifited from a slightly different crop if the tree was more to the right and there was some more negative space I think it could have been more striking.', '2008-03-03 12:55:00.000000', NULL, 1),
(4535282, 649303, 27556, '<td valign="top">Im not impressed with this shot. To me it looks like these random objects were laying around, and happend to be black and white so they were gathered and photographerd. For a still life, for me the object need to be tightly related and on point. The lighting on this shot needs work too. It is very flat.</td>', 'Im not impressed with this shot. To me it looks like these random objects were laying around, and happend to be black and white so they were gathered and photographerd. For a still life, for me the object need to be tightly related and on point. The lighting on this shot needs work too. It is very flat.', '2008-03-03 12:56:32.000000', NULL, 1),
(4535286, 651503, 27556, '<td valign="top">simple, clean and a nice sharp focus. I like the reflection below the egg it is working well in this shot.</td>', 'simple, clean and a nice sharp focus. I like the reflection below the egg it is working well in this shot.', '2008-03-03 12:57:09.000000', NULL, 1),
(4535287, 651707, 27556, '<td valign="top">celver idea but the exicution needs some work. The DOF is fantastic, but the lighting needs some work.</td>', 'celver idea but the exicution needs some work. The DOF is fantastic, but the lighting needs some work.', '2008-03-03 12:57:40.000000', NULL, 1),
(4535289, 650765, 27556, '<td valign="top">It seems like neither the wall nor the shadow are perfectly in focus. This shot had potential and is worth revisiting.</td>', 'It seems like neither the wall nor the shadow are perfectly in focus. This shot had potential and is worth revisiting.', '2008-03-03 12:58:26.000000', NULL, 1),
(4535290, 651568, 27556, '<td valign="top">the lighting needs work, it is very flat. Also the composition could have benifited from the rule of thirds in this case as well instead of being centered.</td>', 'the lighting needs work, it is very flat. Also the composition could have benifited from the rule of thirds in this case as well instead of being centered.', '2008-03-03 12:59:14.000000', NULL, 1),
