(4537811, 651096, 88656, '<td valign="top">I personally like your picture because i am a golfer and CAN''T WAIT till the season starts! But imo the callaway logo in the back is a little distracting from the golf ball. The golf ball also seems a little fuzzy and has some glare, but overall this was a good idea! Good job and good luck this season if you play!</td>', 'I personally like your picture because i am a golfer and CAN''T WAIT till the season starts! But imo the callaway logo in the back is a little distracting from the golf ball. The golf ball also seems a little fuzzy and has some glare, but overall this was a good idea! Good job and good luck this season if you play!', '2008-03-04 14:50:13.000000', NULL, 1),
(4537822, 650461, 88656, '<td valign="top">Very cool picture, but what is it??</td>', 'Very cool picture, but what is it??', '2008-03-04 14:53:20.000000', NULL, 1),
(4537903, 652028, 90806, '<td valign="top">Beautiful, though it felt almost a bit sideways.</td>', 'Beautiful, though it felt almost a bit sideways.', '2008-03-04 15:26:54.000000', NULL, 1),
(4537905, 651159, 90806, '<td valign="top">Seems that the front ear is what is in focus but doesn''t have enough contrast to be a focal point for the shot.</td>', 'Seems that the front ear is what is in focus but doesn''t have enough contrast to be a focal point for the shot.', '2008-03-04 15:28:34.000000', NULL, 1),
