(4538593, 651960, 65234, '<td valign="top">Nice lighting and shadows.  Personally, I prefer milk in my coffee, but that would be too colorful for this challenge.</td>', 'Nice lighting and shadows.  Personally, I prefer milk in my coffee, but that would be too colorful for this challenge.', '2008-03-04 21:06:52.000000', NULL, 1),
(4538598, 651979, 65234, '<td valign="top">This looks like it should be a greeting card of some kind.  Not sure what it should say, exactly ... kind of get a lonely, battling the elements feel from this, but there may be a house with hot cocoa just out of view.  I like it.</td>', 'This looks like it should be a greeting card of some kind.  Not sure what it should say, exactly ... kind of get a lonely, battling the elements feel from this, but there may be a house with hot cocoa just out of view.  I like it.', '2008-03-04 21:08:49.000000', NULL, 1),
(4538601, 651186, 65234, '<td valign="top">Looks like a shot out of a history book.</td>', 'Looks like a shot out of a history book.', '2008-03-04 21:09:37.000000', NULL, 1),
(4538604, 651812, 65234, '<td valign="top">Lovely mist and inky water.  Doesn''t look like anything that would need validation, but what do I know?</td>', 'Lovely mist and inky water.  Doesn''t look like anything that would need validation, but what do I know?', '2008-03-04 21:10:32.000000', NULL, 1),
