(4538655, 651765, 65234, '<td valign="top">This looks sad.  Yet it makes me think of the end of analog TV, which means we need to buy an HD TV, which makes my husband happy.  Life is complex.</td>', 'This looks sad.  Yet it makes me think of the end of analog TV, which means we need to buy an HD TV, which makes my husband happy.  Life is complex.', '2008-03-04 21:24:38.000000', NULL, 1),
(4538658, 651635, 65234, '<td valign="top">This is a fun picture :-)  Love the hair hanging down and the spots on the skirt echoing the spots on the stairs.</td>', 'This is a fun picture :-)  Love the hair hanging down and the spots on the skirt echoing the spots on the stairs.', '2008-03-04 21:25:59.000000', NULL, 1),
(4538662, 650426, 65234, '<td valign="top">Looks like a moon in a milky galaxy.  Cool effect.</td>', 'Looks like a moon in a milky galaxy.  Cool effect.', '2008-03-04 21:27:02.000000', NULL, 1),
(4538664, 650099, 65234, '<td valign="top">Excellent choice of background :-)</td>', 'Excellent choice of background :-)', '2008-03-04 21:27:36.000000', NULL, 1),
