INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4538761, 650596, 48697, '<td valign="top">Lovely scene and well done. I do feel that this streches the theme of the challenge. I see the cows, which I assume are the black and white for the photo, but they are small and hardley noticable it seems to be a shoehorn for the challenge, imo.</td>', 'Lovely scene and well done. I do feel that this streches the theme of the challenge. I see the cows, which I assume are the black and white for the photo, but they are small and hardley noticable it seems to be a shoehorn for the challenge, imo.', '2008-03-04 22:00:52.000000', NULL, 1),
(4538763, 649922, 68947, '<td valign="top">Very nice!</td>', 'Very nice!', '2008-03-04 22:01:23.000000', NULL, 1),
(4538765, 651382, 48697, '<td valign="top">They look like balloons, a modern art piece.</td>', 'They look like balloons, a modern art piece.', '2008-03-04 22:01:37.000000', NULL, 1),
(4538766, 649288, 48697, '<td valign="top">nice simple shot!</td>', 'nice simple shot!', '2008-03-04 22:01:58.000000', NULL, 1),
(4538768, 652021, 68947, '<td valign="top">How adorable!</td>', 'How adorable!', '2008-03-04 22:02:31.000000', NULL, 1),
(4538771, 651664, 68947, '<td valign="top">love the feel to this</td>', 'love the feel to this', '2008-03-04 22:03:23.000000', NULL, 1),
